          {branches.map((b, i) => <div key={b.id} style={{ padding: "11px 18px", borderBottom: i < branches.length - 1 ? `1px solid ${BORDER}` : "none", display: "flex", alignItems: "center", justifyContent: "space-between" }}><div><p style={{ margin: 0, fontSize: 12, fontWeight: 600, color: BLACK }}>{b.name}</p><p style={{ margin: 0, fontSize: 11, color: MUTED }}>{b.phone}</p></div><span style={{ fontSize: 10, fontWeight: 700, padding: "2px 9px", borderRadius: 12, background: b.active ? "#dcfce7" : "#fee2e2", color: b.active ? "#15803d" : "#b91c1c" }}>{b.active ? "Active" : "Inactive"}</span></div>)}
