        {catForm.show ? <Card style={{ padding: "12px" }}><Input value={catForm.name} onChange={v => setCatForm(f => ({ ...f, name: v }))} placeholder="Category name" /><div style={{ display: "flex", gap: 6, marginTop: 8 }}><BSolid small onClick={() => { if (!catForm.name.trim()) return; setCats(p => [...p, { id: "cat" + uid(), label: catForm.name.trim(), services: [] }]); setCatForm({ show: false, name: "" }); }}>Add</BSolid><BOutline small onClick={() => setCatForm({ show: false, name: "" })}>Cancel</BOutline></div></Card>
          : <button onClick={() => setCatForm({ show: true, name: "" })} style={{ background: WHITE, border: `1px dashed ${BORDER}`, borderRadius: 6, padding: "10px", fontSize: 11, fontWeight: 700, color: MUTED, cursor: "pointer", width: "100%" }}>+ New Category</button>}
